import { Unbounded, Noto_Sans_KR } from "next/font/google";

/**
 * TIDE 물결 — a liquid-motion studio. The voice is a swell: round, full,
 * gravitational. Unbounded — a heavy, slightly inflated geometric display
 * that reads like a droplet catching light; the wordmark and kickers.
 * Noto Sans KR (300/500) — the clean Hangul weight that floats on water.
 *
 * styles.css consumes these as var(--font-unbounded) / var(--font-noto-sans-kr);
 * page.tsx applies the .variable classes on the entry root.
 */
export const unbounded = Unbounded({
  weight: ["300", "500", "700", "900"],
  subsets: ["latin"],
  variable: "--font-unbounded",
  display: "swap",
});

export const notoSansKR = Noto_Sans_KR({
  weight: ["300", "400", "500", "700"],
  subsets: ["latin"],
  variable: "--font-noto-sans-kr",
  display: "swap",
});

"use client";

import { useSyncExternalStore } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

function subscribe(onChange: () => void): () => void {
  const mql = window.matchMedia(QUERY);
  mql.addEventListener("change", onChange);
  return () => mql.removeEventListener("change", onChange);
}

function getSnapshot(): boolean {
  return window.matchMedia(QUERY).matches;
}

function getServerSnapshot(): boolean {
  return false;
}

/**
 * True when the OS asks for reduced motion.
 * SSR-safe: the server snapshot is `false`; on the client the real value is
 * read synchronously, and live changes to the setting re-render immediately.
 */
export function usePrefersReducedMotion(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

"use client";

import { useEffect, useRef } from "react";
import { usePrefersReducedMotion } from "./usePrefersReducedMotion";

/**
 * Reveals descendants marked with [data-reveal] as they enter the viewport,
 * by adding an `is-visible` class (the name styles.css expects). Pre-reveal
 * states (opacity/translate) live in styles.css and are gated behind the
 * `.neon-js` root class, so all content is fully visible when JavaScript
 * never runs.
 *
 * Elements that intersect in the same observer batch are staggered 80ms apart
 * — the street's cadence.
 */
export function useReveal<T extends HTMLElement = HTMLElement>() {
  const ref = useRef<T | null>(null);
  const reduced = usePrefersReducedMotion();

  useEffect(() => {
    const root = ref.current;
    if (!root) return;
    const targets = Array.from(
      root.querySelectorAll<HTMLElement>("[data-reveal]"),
    );

    if (reduced || !("IntersectionObserver" in window)) {
      for (const el of targets) el.classList.add("is-visible");
      return;
    }

    const io = new IntersectionObserver(
      (hits) => {
        let batch = 0;
        for (const hit of hits) {
          if (!hit.isIntersecting) continue;
          const el = hit.target as HTMLElement;
          el.style.transitionDelay = `${batch * 80}ms`;
          el.classList.add("is-visible");
          io.unobserve(el);
          batch += 1;
        }
      },
      { threshold: 0.16, rootMargin: "0px 0px -8% 0px" },
    );
    for (const el of targets) io.observe(el);
    return () => io.disconnect();
  }, [reduced]);

  return ref;
}

"use client";

import { useEffect, useRef, type CSSProperties } from "react";
import "./styles.css";
import { unbounded, notoSansKR } from "./fonts";
import { useReveal } from "./hooks/useReveal";
import { usePrefersReducedMotion } from "./hooks/usePrefersReducedMotion";

const TITLE = "TIDE";

/**
 * TIDE 물결 — a liquid-motion studio. The signature is a metaball field drawn
 * on canvas 2D: a handful of liquid blobs that orbit, merge, and pull toward
 * the pointer. The blobs are drawn as soft radial gradients over an additive
 * threshold, so overlaps bloom into one body of water. Under reduced motion
 * the field is a single composed swell (a still you can read).
 *
 * `.tide-js` is added on mount so the no-JS markup is the finished page: the
 * field is a CSS gradient understudy, the wordmark sits, copy is readable.
 */
export default function TidePage() {
  const rootRef = useRef<HTMLDivElement | null>(null);
  const reduced = usePrefersReducedMotion();
  const revealRef = useReveal<HTMLDivElement>();
  const canvasRef = useRef<HTMLCanvasElement | null>(null);

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    root.classList.add("tide-js");
    const id = requestAnimationFrame(() => root.classList.add("is-mounted"));
    window.parent?.postMessage({ type: "oneshot:ready", slug: "tide" }, "*");
    return () => cancelAnimationFrame(id);
  }, []);

  // Metaball liquid field. A few orbiting blobs + one that follows the pointer.
  // Drawn as stacked radial gradients with 'lighter' compositing so overlaps
  // bloom; a vignette keeps the edge calm.
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const COLORS = ["#37e2c5", "#2ec0ff", "#5d8bff", "#9b6bff"];
    let w = 0;
    let h = 0;
    let dpr = 1;
    const blobs: { x: number; y: number; r: number; phase: number; speed: number; ax: number; ay: number; ci: number }[] = [];
    const N = 7;
    for (let i = 0; i < N; i++) {
      blobs.push({
        x: 0, y: 0,
        r: 60 + Math.random() * 80,
        phase: Math.random() * Math.PI * 2,
        speed: 0.18 + Math.random() * 0.22,
        ax: 0.5 + Math.random() * 0.5,
        ay: 0.4 + Math.random() * 0.5,
        ci: i % COLORS.length,
      });
    }
    const ptr = { x: 0.5, y: 0.5, tx: 0.5, ty: 0.5 };

    const resize = () => {
      const rect = canvas.getBoundingClientRect();
      w = rect.width;
      h = rect.height;
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.round(w * dpr);
      canvas.height = Math.round(h * dpr);
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    };
    resize();

    const onMove = (e: PointerEvent) => {
      const rect = canvas.getBoundingClientRect();
      ptr.tx = (e.clientX - rect.left) / rect.width;
      ptr.ty = (e.clientY - rect.top) / rect.height;
    };
    window.addEventListener("pointermove", onMove, { passive: true });
    window.addEventListener("resize", resize);

    let raf = 0;
    let t = 0;
    let last = performance.now();
    const draw = (now: number) => {
      raf = requestAnimationFrame(draw);
      const dt = Math.min(48, now - last) / 1000;
      last = now;
      t += dt;

      // pointer-follow blob eases toward target; others orbit.
      ptr.x += (ptr.tx - ptr.x) * 0.06;
      ptr.y += (ptr.ty - ptr.y) * 0.06;

      ctx.globalCompositeOperation = "source-over";
      ctx.fillStyle = "#04101a";
      ctx.fillRect(0, 0, w, h);

      ctx.globalCompositeOperation = "lighter";
      for (let i = 0; i < blobs.length; i++) {
        const b = blobs[i];
        if (i === 0 && !reduced) {
          // pointer blob
          b.x = ptr.x * w;
          b.y = ptr.y * h;
        } else {
          b.phase += b.speed * dt * (reduced ? 0 : 1);
          b.x = w * (0.5 + Math.cos(b.phase) * 0.34 * b.ax);
          b.y = h * (0.5 + Math.sin(b.phase * 0.8 + i) * 0.34 * b.ay);
        }
        const r = b.r * (1 + 0.12 * Math.sin(t * 1.2 + i));
        const grad = ctx.createRadialGradient(b.x, b.y, 0, b.x, b.y, r * 2.1);
        const c = COLORS[b.ci];
        grad.addColorStop(0, hexA(c, 0.9));
        grad.addColorStop(0.4, hexA(c, 0.5));
        grad.addColorStop(1, hexA(c, 0));
        ctx.fillStyle = grad;
        ctx.beginPath();
        ctx.arc(b.x, b.y, r * 2.1, 0, Math.PI * 2);
        ctx.fill();
      }

      // edge vignette so the liquid pools in the center.
      ctx.globalCompositeOperation = "source-over";
      const vg = ctx.createRadialGradient(w / 2, h / 2, Math.min(w, h) * 0.2, w / 2, h / 2, Math.max(w, h) * 0.75);
      vg.addColorStop(0, "rgba(4,16,26,0)");
      vg.addColorStop(1, "rgba(4,16,26,0.86)");
      ctx.fillStyle = vg;
      ctx.fillRect(0, 0, w, h);
    };
    raf = requestAnimationFrame(draw);
    return () => {
      cancelAnimationFrame(raf);
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("resize", resize);
    };
  }, [reduced]);

  return (
    <div ref={rootRef} className={`${unbounded.variable} ${notoSansKR.variable} tide-root`}>
      <canvas ref={canvasRef} className="tide-field" aria-hidden="true" />
      <div className="tide-scrim" aria-hidden="true" />
      <div ref={revealRef} className="tide-doc">
        <header className="tide-hero">
          <p className="tide-kicker">
            <span lang="ko">액체 모션 스튜디오</span> · LIQUID MOTION STUDIO
          </p>
          <h1 className="tide-title" aria-label={TITLE}>
            {TITLE.split("").map((ch, i) => (
              <span
                key={i}
                aria-hidden="true"
                className="tide-glyph"
                style={{ "--td-i": i } as CSSProperties}
              >
                {ch}
              </span>
            ))}
          </h1>
          <p className="tide-title__ko" lang="ko">물결</p>
          <p className="tide-sub">
            <span lang="ko">흐르는 것을 위한 스튜디오.</span> A studio for things that flow.
          </p>
          <p className="tide-hint" lang="ko">움직여 보세요 — 물이 당신을 따라옵니다.</p>
        </header>

        <main>
          <section className="tide-lead" data-reveal>
            <p className="tide-lead__p">
              <span lang="ko">
                밀물과 썰물은 밀고 당기는 힘이다. 우리는 인터페이스를 액체로 생각한다 —
                합쳤다가 갈라지고, 손가락을 따라 모이고, 멈추면 잔잔한 호수가 된다.
              </span>{" "}
              A tide is a push and pull. We think of interface as liquid — merging
              and parting, gathering toward the finger, settling into a still lake
              when at rest.
            </p>
          </section>

          <section className="tide-cards">
            {[
              { ko: "유변", en: "Rheology", n: "01" },
              { ko: "표면장력", en: "Surface tension", n: "02" },
              { ko: "파동", en: "Wave", n: "03" },
            ].map((c, i) => (
              <article key={i} className="tide-card" data-reveal style={{ "--td-d": i * 90 } as CSSProperties}>
                <span className="tide-card__n">{c.n}</span>
                <span className="tide-card__en">{c.en}</span>
                <span className="tide-card__ko" lang="ko">{c.ko}</span>
              </article>
            ))}
          </section>
        </main>

        <footer className="tide-foot">
          <span>TIDE · 2026</span>
          <span lang="ko">물결 — 부산 해운대</span>
        </footer>
      </div>
    </div>
  );
}

/** hex (#rrggbb) -> rgba() with alpha. */
function hexA(hex: string, a: number): string {
  const h = hex.replace("#", "");
  const r = parseInt(h.slice(0, 2), 16);
  const g = parseInt(h.slice(2, 4), 16);
  const b = parseInt(h.slice(4, 6), 16);
  return `rgba(${r},${g},${b},${a})`;
}

.tide-root {
  --td-bg: #04101a;
  --td-deep: #020a12;
  --td-text: #e6fbff;
  --td-mute: #7fa9b8;
  --td-cyan: #37e2c5;
  --td-blue: #2ec0ff;
  --td-font-display: var(--font-unbounded), "Unbounded", system-ui, sans-serif;
  --td-font-kr: var(--font-noto-sans-kr), "Noto Sans KR", sans-serif;
  --td-ease: cubic-bezier(0.16, 1, 0.3, 1);

  position: relative;
  min-height: 100vh;
  margin: 0;
  background: var(--td-bg);
  color: var(--td-text);
  font-family: var(--td-font-kr);
  font-weight: 300;
  line-height: 1.6;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
}

/* CSS understudy field, shown when JS/canvas is absent or still mounting. */
.tide-field {
  position: fixed;
  inset: 0;
  width: 100vw;
  height: 100vh;
  z-index: 0;
  display: block;
  /* no-JS gradient understudy: a calm teal-blue pool. */
  background:
    radial-gradient(50% 60% at 30% 35%, rgba(55, 226, 197, 0.5), transparent 70%),
    radial-gradient(48% 56% at 72% 60%, rgba(46, 192, 255, 0.45), transparent 72%),
    radial-gradient(60% 70% at 50% 90%, rgba(91, 139, 255, 0.35), transparent 72%),
    var(--td-bg);
}
.tide-scrim {
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  background:
    linear-gradient(180deg, rgba(4, 16, 26, 0.55) 0%, transparent 30%, transparent 60%, rgba(4, 16, 26, 0.8) 100%);
}

.tide-doc {
  position: relative;
  z-index: 1;
  max-width: 1180px;
  margin: 0 auto;
  padding: clamp(1.5rem, 4vw, 3.5rem);
}

.tide-root ::selection {
  background: var(--td-cyan);
  color: var(--td-deep);
}

/* ---- Hero ---- */
.tide-hero {
  min-height: 88vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: clamp(3rem, 10vh, 7rem) 0 2rem;
}
.tide-kicker {
  margin: 0 0 1.4rem;
  font-family: var(--td-font-display);
  font-size: clamp(0.72rem, 1.1vw, 0.86rem);
  font-weight: 500;
  letter-spacing: 0.42em;
  text-transform: uppercase;
  color: var(--td-cyan);
}
.tide-title {
  margin: 0;
  font-family: var(--td-font-display);
  font-weight: 900;
  font-size: clamp(4rem, 20vw, 16rem);
  line-height: 0.88;
  letter-spacing: -0.04em;
  text-transform: uppercase;
  color: #f0feff;
  /* liquid droplet: a wet highlight on top + a deep waterline drop. */
  text-shadow:
    0 2px 0 rgba(255, 255, 255, 0.5),
    0 14px 40px rgba(55, 226, 197, 0.4),
    0 4px 10px rgba(2, 10, 18, 0.6);
}
.tide-glyph { display: inline-block; }
.tide-title__ko {
  margin: 0.6rem 0 0;
  font-family: var(--td-font-kr);
  font-weight: 300;
  font-size: clamp(1rem, 2.4vw, 1.6rem);
  letter-spacing: 0.5em;
  color: var(--td-mute);
}
.tide-sub {
  margin: 1.6rem 0 0.5rem;
  font-size: clamp(1.05rem, 1.9vw, 1.4rem);
  font-weight: 400;
}
.tide-sub span[lang="ko"] { color: var(--td-mute); margin-right: 0.5rem; }
.tide-hint {
  margin: 0;
  font-size: 0.86rem;
  color: var(--td-cyan);
  letter-spacing: 0.04em;
  opacity: 0.85;
}

/* ---- Lead ---- */
.tide-lead {
  padding: clamp(2.5rem, 6vw, 4rem) 0;
  border-top: 1px solid rgba(55, 226, 197, 0.16);
}
.tide-lead__p {
  margin: 0 auto;
  max-width: 62ch;
  font-family: var(--td-font-display);
  font-weight: 300;
  font-size: clamp(1.15rem, 2.4vw, 1.7rem);
  line-height: 1.5;
  text-align: center;
}
.tide-lead__p span[lang="ko"] {
  display: block;
  font-family: var(--td-font-kr);
  color: var(--td-mute);
  font-size: 0.74em;
  margin-bottom: 0.6em;
}

/* ---- Cards ---- */
.tide-cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: clamp(0.9rem, 1.6vw, 1.3rem);
  padding-bottom: clamp(2rem, 5vw, 3rem);
}
.tide-card {
  position: relative;
  padding: clamp(1.2rem, 2.4vw, 1.8rem);
  border-radius: 18px;
  background: rgba(8, 28, 40, 0.42);
  border: 1px solid rgba(55, 226, 197, 0.2);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.12), 0 20px 40px -24px rgba(2, 10, 18, 0.8);
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  min-height: 150px;
}
.tide-card__n {
  font-family: var(--td-font-display);
  font-weight: 700;
  font-size: 0.8rem;
  color: var(--td-cyan);
  letter-spacing: 0.2em;
}
.tide-card__en {
  font-family: var(--td-font-display);
  font-weight: 500;
  font-size: 1.2rem;
}
.tide-card__ko { font-size: 0.9rem; color: var(--td-mute); }

.tide-foot {
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 0.5rem;
  padding: clamp(2rem, 5vw, 3rem) 0;
  border-top: 1px solid rgba(55, 226, 197, 0.16);
  font-size: 0.8rem;
  letter-spacing: 0.06em;
  color: var(--td-mute);
  font-family: var(--td-font-display);
}

/* ---- Reveal gating ---- */
.tide-js [data-reveal] {
  opacity: 0;
  transform: translateY(26px);
  transition: opacity 800ms var(--td-ease), transform 800ms var(--td-ease);
}
.tide-js [data-reveal].is-visible { opacity: 1; transform: none; }
.tide-js [data-reveal] { transition-delay: calc(var(--td-d, 0) * 1ms); }
.tide-js .tide-glyph {
  opacity: 0;
  transform: translateY(0.4em);
  display: inline-block;
  transition: opacity 600ms var(--td-ease), transform 700ms var(--td-ease);
  transition-delay: calc(var(--td-i) * 90ms + 150ms);
}
.tide-js.is-mounted .tide-glyph { opacity: 1; transform: none; }

@media (prefers-reduced-motion: reduce) {
  .tide-js [data-reveal], .tide-js .tide-glyph {
    opacity: 1 !important; transform: none !important; transition: none !important;
  }
}

.tide-root :focus-visible {
  outline: 2px solid var(--td-cyan);
  outline-offset: 3px;
}
